<?php
declare(strict_types=1); namespace Comfino\Shop\Order; use Comfino\Shop\Order\Cart\CartItemInterface; class Cart implements CartInterface{ private $items; private $totalAmount; private $deliveryCost; private $deliveryNetCost; private $deliveryCostTaxRate; private $deliveryCostTaxValue; private $category; public function __construct(array$items,int $totalAmount,?int $deliveryCost=null,?int $deliveryNetCost=null,?int $deliveryCostTaxRate=null,?int $deliveryCostTaxValue=null,?string $category=null){$this->items=$items;$this->totalAmount=$totalAmount;$this->deliveryCost=$deliveryCost;$this->deliveryNetCost=$deliveryNetCost;$this->deliveryCostTaxRate=$deliveryCostTaxRate;$this->deliveryCostTaxValue=$deliveryCostTaxValue;$this->category=$category;}public function getItems():array{return $this->items;}public function getTotalAmount():int{return $this->totalAmount;}public function getDeliveryCost():?int{return $this->deliveryCost;}public function getDeliveryNetCost():?int{return $this->deliveryNetCost;}public function getDeliveryCostTaxRate():?int{return $this->deliveryCostTaxRate;}public function getDeliveryCostTaxValue():?int{return $this->deliveryCostTaxValue;}public function getCategory():?string{return $this->category;}}